function getCorsHeaders(request) {
    const origin = (request && request.headers) ? (request.headers.get('Origin') || '') : '';
    const allowedOrigins = [
        'http://localhost:5500',
        'http://127.0.0.1:5500',
        'http://localhost:8787',
        'http://127.0.0.1:8787',
        'http://localhost:3000',
        'http://127.0.0.1:3000',
        'http://localhost:5173',
        'http://127.0.0.1:5173',
        'https://smartfinance-webapp.onrender.com'
    ];

    let allowOrigin = null;
    if (allowedOrigins.includes(origin)) {
        allowOrigin = origin;
    } else if (origin && origin.endsWith('.onrender.com')) {
        allowOrigin = origin;
    } else if (!origin) {
        allowOrigin = 'https://smartfinance-webapp.onrender.com';
    }

    return {
        'Access-Control-Allow-Origin': allowOrigin || 'https://smartfinance-webapp.onrender.com',
        'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Test-Mode',
        'Access-Control-Max-Age': '86400',
        'Vary': 'Origin'
    };
}

function getJwtSecret(env) {
    if (env && env.JWT_SECRET) return env.JWT_SECRET;
    if (env && (env.ENVIRONMENT === 'dev' || env.ENVIRONMENT === 'test' || !env.ENVIRONMENT)) {
        return 'dev_only_local_jwt_secret_do_not_use_in_prod';
    }
    throw new Error('JWT_SECRET configuration is missing on Cloudflare Worker.');
}

